styles.css.data:
.navopath-daily-overview { color: var(--text-main); min-width: 0; }
.navopath-daily-overview-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding-bottom: 18px; border-bottom: 1px solid var(--border-soft); }
.navopath-daily-overview-heading h2 { margin: 0; font: 600 24px/1.2 var(--paper-display, var(--font-display, inherit)); }
.navopath-daily-overview-date { margin: 6px 0 0; color: var(--text-secondary, var(--text-main)); font-size: 13px; }
.navopath-daily-overview-summary { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin: 18px 0 22px; }
.navopath-daily-overview-metric { min-width: 0; display: flex; flex-direction: column; gap: 5px; padding: 12px; border: 1px solid var(--border-soft); border-radius: var(--radius-card, 10px); background: var(--surface-soft, var(--surface-main)); }
.navopath-daily-overview-metric strong { font: 600 24px/1 var(--paper-mono, monospace); }
.navopath-daily-overview-metric span { color: var(--text-secondary, var(--text-main)); font-size: 12px; overflow-wrap: anywhere; }
.navopath-daily-overview-sections { display: grid; gap: 18px; }
.navopath-daily-overview-group { min-width: 0; }
.navopath-daily-overview-group h3 { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; font-size: 14px; font-weight: 600; }
.navopath-daily-overview-count { color: var(--text-secondary, var(--text-main)); font: 500 11px/1 var(--paper-mono, monospace); }
.navopath-daily-overview-group ul { padding: 0; margin: 0; list-style: none; }
.navopath-daily-overview-group li { padding: 10px 0; border-bottom: 1px solid var(--border-soft); overflow-wrap: anywhere; font-size: 13px; line-height: 1.5; }
.navopath-daily-overview-empty { margin: 0; padding: 12px; border: 1px dashed var(--border-soft); border-radius: var(--radius-card, 10px); color: var(--text-secondary, var(--text-main)); font-size: 13px; }
@media (max-width: 380px) { .navopath-daily-overview-summary { gap: 6px; } .navopath-daily-overview-metric { padding: 9px; } .navopath-daily-overview-metric strong { font-size: 20px; } }
